<template><section ref="historyPanel" class="unwrap-tool-section"><p class="tool-note">{{zh?'1. 计算裁线并检查预览 → 2. 确认版型并保存':localize('1. Compute and inspect cut lines → 2. Accept and save patterns')}}</p><div class="unwrap-controls"><div class="cut-allowance"><label>{{zh?'拼接间距大小 cm（0–10）':localize('Joining spacing size cm (0–10)')}}<input v-model.number="allowanceCm" v-decimal type="number" min="0" max="10" step=".1" :aria-label="zh?'拼接间距大小 cm':localize('Joining spacing size cm')" :disabled="store.busy"></label><span>{{Number((allowanceCm*10).toFixed(6))}} mm</span><button :disabled="store.busy||!allowanceValid||!store.data.project" @click="applyAllowance">{{zh?'应用拼接间距':localize('Apply joining spacing')}}</button><small>{{zh?'应用到所有当前裁片；0 表示不加拼接间距。可撤销，裁切库保留原快照。':localize('Applies to all current patterns; 0 adds no joining spacing. Undo is available; saved cuts retain their snapshots.')}}</small><small v-if="!allowanceValid" role="alert">{{zh?'请输入 0–10 cm 范围内的数值。':localize('Enter a value from 0 to 10 cm.')}}</small></div><label v-if="advanced">{{zh?'展开算法':localize('Unwrap solver')}}<select v-model="unwrapOptions.method"><option value="lscm">LSCM</option><option value="arap">LSCM + ARAP</option></select></label><label v-if="advanced"><input v-model="unwrapOptions.automaticCuts" type="checkbox">{{zh?'自动切缝':localize('Automatic cuts')}}</label><label v-if="advanced"><input v-model="unwrapOptions.optimizeCuts" type="checkbox">{{zh?'高失真试切优化':localize('Trial cuts for high distortion')}}</label><label><input :checked="unwrapOptions.colorBoundaryCuts" type="checkbox" @change="colorMode(($event.target as HTMLInputElement).checked)">{{zh?'按花纹颜色拆分裁片':localize('Separate pieces at color boundaries')}}</label><small>{{zh?'默认按颜色边界与自定义裁线形成裁片，仅在展开需要时补缝；请审阅接缝与失真。':localize('Color boundaries and custom cut lines define the pieces. Necessary unwrap seams may be added; review seams and distortion.')}}</small><label v-if="advanced&&unwrapOptions.partitionStrategy==='mesh'&&unwrapOptions.colorBoundaryCuts">{{zh?'自动分片策略':localize('Automatic partition strategy')}}<select :value="unwrapOptions.normalAngleDeg" @change="partitionMode(Number(($event.target as HTMLSelectElement).value))" :aria-label="zh?'自动分片策略':localize('Automatic partition strategy')"><option :value="120">{{zh?'较少额外接缝':localize('Fewer additional seams')}}</option><option :value="60">{{zh?'更细的曲面分片':localize('Finer surface patches')}}</option><option v-if="![60,120].includes(unwrapOptions.normalAngleDeg??60)" :value="unwrapOptions.normalAngleDeg">{{zh?'自定义':localize('Custom')}} · {{unwrapOptions.normalAngleDeg}}°</option></select></label><small v-if="advanced&&unwrapOptions.partitionStrategy==='mesh'&&unwrapOptions.colorBoundaryCuts">{{zh?'颜色边界会继续拆分裁片。较少额外接缝可减少碎片，仍需审阅曲面失真；自定义裁剪线会保留。':localize('Color boundaries split the patches further. Fewer additional seams reduces fragmentation; review surface distortion. Custom cut lines are preserved.')}}</small><label v-if="advanced">{{zh?'分片方式':localize('Partition mode')}}<select v-model="unwrapOptions.partitionStrategy" aria-label="分片方式"><option value="design">{{zh?'按颜色与裁线设计':localize('Color and cut-line design')}}</option><option value="mesh">{{zh?'按网格分片（兼容模式）':localize('Mesh patches (compatibility)')}}</option></select></label><details v-if="advanced" class="solver-settings"><summary>{{zh?'求解参数':localize('Solver settings')}}</summary><label v-if="unwrapOptions.partitionStrategy==='mesh'">{{zh?'法线分片角度 °':localize('Normal angle °')}}<input v-model.number="unwrapOptions.normalAngleDeg" type="number" min="5" max="180"></label><label v-if="unwrapOptions.partitionStrategy==='mesh'">{{zh?'每片最大面数':localize('Faces per patch')}}<input v-model.number="unwrapOptions.maxFacesPerPatch" type="number" min="1" max="2000"></label><label>{{zh?'迭代次数':localize('Iterations')}}<input v-model.number="unwrapOptions.iterations" type="number" min="1" max="100"></label><label>{{zh?'试切搜索轮次':localize('Cut search passes')}}<input v-model.number="unwrapOptions.searchPasses" type="number" min="1" max="5"></label><label>{{zh?'最大裁片数':localize('Maximum pieces')}}<input v-model.number="unwrapOptions.maxPieces" type="number" min="2" max="500"></label></details><Teleport :to="actionTarget??'body'" :disabled="!actionTarget" defer><div class="compute-cut-action"><small v-if="!store.busy&&store.error==='TIMEOUT'" class="cut-timeout" role="alert">{{zh?'裁切已达到 60 秒时限，原项目已保留。请缩小本次制版范围或补充裁线后重试。':localize('Cutting reached the 60-second limit. Your project is preserved. Reduce the cutting scope or add cut lines, then retry.')}}</small><button class="compute-cut-preview" :class="{'in-workspace-toolbar':!!actionTarget}" :disabled="store.busy||cutDraftActive||!surface||!allowanceValid" :title="zh?'裁切并计算版型预览':localize('Cut and compute pattern preview')" @click="unwrap"><span v-if="unwrapping&&store.working" class="cut-task-spinner" aria-hidden="true"/><ToolIcon v-else name="cut"/><span>{{unwrapping&&store.working?(zh?'正在计算裁线…':localize('Computing cut lines…')):(zh?'自动计算裁线并预览':localize('Compute & preview cut lines'))}}</span></button><small v-if="cutDraftActive" class="pending-cut-draft" role="status">{{zh?'先保存或取消裁线草稿，再计算。':localize('Save or cancel the cut draft before computing.')}}</small><div v-if="unwrapping&&store.working" class="surface-progress" role="status" aria-live="polite"><div><strong>{{store.cancelling?(zh?'正在取消展开…':localize('Cancelling unwrap…')):stageLabel}}</strong><span v-if="progress?.completed!==undefined"> · {{progress.completed}}<template v-if="progress.total!==undefined"> / {{progress.total}}</template><template v-if="progress.stage==='unwrap'"> {{zh?'面':localize('faces')}}</template></span><span aria-hidden="true"> · {{zh?'已运行':localize('Elapsed')}} {{elapsedSeconds}} {{zh?'秒':localize('seconds')}}</span></div><progress v-if="progress?.total&&progress.completed!==undefined" :value="progress.completed" :max="progress.total" :aria-label="stageLabel"/><button :disabled="store.cancelling" @click="store.cancelRun()">{{store.cancelling?(zh?'正在取消…':localize('Cancelling…')):(zh?'取消展开':localize('Cancel unwrap'))}}</button></div></div></Teleport></div><p v-if="!surface" class="tool-note">{{zh?'先在“模型管理”页面导入或创建模型。':localize('Import or create a model first.')}}</p> <section v-if="run" class="run-report"><small v-if="advanced&&run.bindings.some(b=>b.report.planarExact)">{{zh?'共面片使用精确毫米投影；轮廓冗余采样清理容差 0.0001 mm。':localize('Planar patches use an exact millimetre projection; redundant boundary tolerance 0.0001 mm.')}}</small><div v-if="!run.accepted" class="candidate-cut-review" role="status"><ToolIcon name="eye"/><div><strong>{{zh?'裁线预览已生成':localize('Cut-line preview ready')}}</strong><p>{{zh?'检查模型上的裁片边界、补缝与二维轮廓，再确认版型。':localize('Inspect piece boundaries, added seams and 2D outlines before accepting the patterns.')}}</p><button :disabled="store.busy" @click="emit('mapping')">{{zh?'在映射页查看裁线':localize('Inspect cut lines in mapping')}}</button></div></div><strong>{{run.algorithm}} · {{run.pieces.length}} {{zh?'片':localize('pieces')}} · {{run.accepted?(zh?'已接受':localize('Accepted')):(zh?'待检查':localize('Ready for review'))}}</strong><button v-if="run.accepted" :disabled="store.busy" @click="emit('mapping')">{{zh?'在映射页查看已保存裁线':localize('Inspect saved cut seams in mapping')}}</button><p>{{zh?'最大面积误差':localize('Maximum area error')}} {{(run.bindings.reduce((max,b)=>Math.max(max,b.report.areaErrorMax),0)*100).toFixed(2)}}% · {{zh?'最大边长误差':localize('Maximum edge error')}} {{(run.bindings.reduce((max,b)=>Math.max(max,b.report.edgeErrorMax),0)*100).toFixed(2)}}%</p><p v-if="run.designCutReport" class="design-cut-report">{{zh?'设计材料域':localize('Designed material domains')}} {{run.designCutReport.materialDomains}} · {{zh?'自定义裁线':localize('User cut lines')}} {{run.designCutReport.userSeams}} · {{zh?'必要补缝':localize('Necessary additional seams')}}: {{zh?'拓扑开口':localize('Topology')}} {{run.designCutReport.topologySeams}} / {{zh?'失真修正':localize('Distortion')}} {{run.designCutReport.distortionSeams}} / {{zh?'拼接间距制造':localize('Manufacturing allowance')}} {{run.designCutReport.manufacturingSeams}}。{{zh?'请在拼接预览检查补缝并审阅失真。':localize('Inspect additional seams and distortion in Cut assembly.')}}</p><p v-if="run.colorCutReport&&(run.colorCutReport.budgetSplits+run.colorCutReport.allowanceSplits+run.colorCutReport.topologySplits)>0" class="color-cut-report">{{zh?'为保留材料并生成可制造裁片，已增加分片接缝：':localize('Additional seams preserve material and produce manufacturable pieces:')}} {{zh?'复杂轮廓':localize('Detailed contours')}} {{run.colorCutReport.budgetSplits}} · {{zh?'内孔拼接间距':localize('Hole allowances')}} {{run.colorCutReport.allowanceSplits}} · {{zh?'相切边界':localize('Touching boundaries')}} {{run.colorCutReport.topologySplits}}。{{zh?'请在组合预览中检查这些接缝。':localize('Inspect these seams in the assembly preview.')}}</p><details v-if="advanced" class="tool-details"><summary>{{zh?'逐片失真与求解报告':localize('Piece distortion & solver report')}}</summary><div v-for="(binding,i) in run.bindings" :key="binding.pieceId">{{i+1}} · {{binding.report.status}} · {{zh?'面积最大误差':localize('Max area error')}} {{(binding.report.areaErrorMax*100).toFixed(2)}}% · {{zh?'边长最大误差':localize('Max edge error')}} {{(binding.report.edgeErrorMax*100).toFixed(2)}}% · D mean {{binding.report.distortionMean.toFixed(4)}} / p95 {{binding.report.distortionP95.toFixed(4)}} / max {{binding.report.distortionMax.toFixed(4)}}</div>
  <p v-if="run.optimization">{{zh?'试切优化成本':localize('Trial-cut cost')}} {{run.optimization.initialCost.toFixed(5)}} → {{(run.optimization.optimizedCost??run.optimization.finalCost).toFixed(5)}} · {{zh?'补切后成本':localize('Cost after allowance repair')}} {{run.optimization.finalCost.toFixed(5)}} · {{run.optimization.passes}} / {{run.optimization.trials}} · {{zh?'拼接间距补切轮次':localize('Allowance repair passes')}} {{run.optimization.repairPasses??0}}</p><p v-if="run.cutEdges?.length">{{zh?'自动切缝边数':localize('Automatic cut edges')}}: {{run.cutEdges.length}}</p><div v-for="b in run.bindings.filter(b=>b.report.arap)" :key="b.pieceId+'arap'">ARAP {{b.report.arap?.iterations}} · E {{b.report.arap?.energyBefore.toExponential(3)}} → {{b.report.arap?.energyAfter.toExponential(3)}} · {{b.report.arap?.converged?(zh?'已收敛':localize('Converged')):localize('Iteration budget / line search limit')}}</div></details><template v-if="!run.accepted"><p v-if="allowanceChanged||allowanceRecomputeRequired" role="status">{{zh?'拼接间距已修改，请重新计算预览后再确认。':localize('Allowance changed; recompute the preview before accepting.')}}</p><label class="distortion-review" v-if="run.bindings.some(b=>b.report.status==='needsReview')"><input v-model="ack" type="checkbox">{{zh?'我已审阅超出实验阈值的失真，仍需材料试做验证':localize('I reviewed distortion above experimental thresholds; material trials remain necessary')}}</label><button :disabled="store.busy||cutDraftActive||!allowanceValid||allowanceChanged||allowanceRecomputeRequired||run.bindings.some(b=>b.report.status==='needsReview')&&!ack" @click="accept">{{zh?'确认版型并保存到裁切库（可撤销）':localize('Accept patterns and save to library (undoable)')}}</button></template>
 <details v-if="surface" :open="assemblyOpen" @toggle="assemblyOpen=($event.target as HTMLDetailsElement).open"><summary>{{zh?'裁片组合预览':localize('Cut assembly preview')}}</summary><CutAssemblyPreview v-if="assemblyOpen" v-model:selection="assemblySelection" :surface="surface" :run="run" :markings="store.data.project?.previewMarkings??store.data.project?.markings" :language="language"/></details></section>
</section></template>

<script setup lang="ts">
import {localize} from './localization';

import {computed,inject,ref,shallowRef,watch,onMounted,onBeforeUnmount,useTemplateRef} from 'vue';
import {useSession} from './store';
import {patternSpacingMatches} from '../../../packages/manufacturing/pattern-spacing';
import {useDraftHistory} from './modules/useDraftHistory';
import CutAssemblyPreview from './CutAssemblyPreview.vue';
import ToolIcon from './ToolIcon.vue';
import {vDecimal} from './modules/decimal-input';
import type {UnwrapOptions,SurfaceProgress} from '../../../packages/schema/index';
const advanced=inject('advancedMode',ref(false));
const props=defineProps<{language:'zh'|'en';actionTarget?:string;cutDraftActive?:boolean}>(),emit=defineEmits<{accepted:[id:string];previewReady:[];mapping:[]}>(),store=useSession(),zh=computed(()=>props.language==='zh'),surface=computed(()=>store.data.project?.surface),run=computed(()=>store.data.project?.surfaceRun),ack=ref(false),unwrapping=ref(false);
watch(()=>[store.data.project?.id,store.data.project?.revision],()=>{ack.value=false;});
const allowanceCm=ref(1),allowanceValid=computed(()=>Number.isFinite(allowanceCm.value)&&allowanceCm.value>=0&&allowanceCm.value<=10),allowanceChanged=computed(()=>Number((allowanceCm.value*10).toFixed(6))!==(store.data.project?.defaultAllowanceMm??10));
const allowanceRecomputeRequired=ref(false);
const assemblyOpen=ref(false),assemblySelection=shallowRef<{pieceIds:string[];chosen:string[]}>({pieceIds:[],chosen:[]});
watch(()=>store.data.project?.id,()=>{allowanceRecomputeRequired.value=false;});
watch(()=>store.data.project?.defaultAllowanceMm,(next,previous)=>{if(next!==previous&&run.value&&!run.value.accepted)allowanceRecomputeRequired.value=true;});
watch(()=>[store.data.project?.id,store.data.project?.defaultAllowanceMm],()=>{allowanceCm.value=(store.data.project?.defaultAllowanceMm??10)/10;},{immediate:true});
async function applyAllowance(){const p=store.data.project;if(!p||store.busy||!allowanceValid.value)return false;const widthMm=Number((allowanceCm.value*10).toFixed(6));if(patternSpacingMatches(p,widthMm))return true;return store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'patterns.allowance',widthMm}),{label:zh.value?'正在应用所有裁片的拼接间距':localize('Applying joining spacing to all patterns'),cancel:()=>window.fpcad.cancelSurface(p.id,p.revision)});}
const progress=shallowRef<SurfaceProgress>(),activeCut=shallowRef<{projectId:string;revision:number}>(),elapsedSeconds=ref(0);
const stageLabel=computed(()=>{const stage=progress.value?.stage;return localize(stage?({prepare:zh.value?'准备裁切':'Preparing cuts',partition:zh.value?'划分材料与裁线':'Partitioning materials and cuts',unwrap:zh.value?'展开裁片':'Unwrapping pieces',remap:zh.value?'映射花纹':'Remapping markings',validate:zh.value?'校验版型':'Validating patterns'}[stage]):(zh.value?'等待裁切任务':'Waiting for the cut task'));});
let disposed=false,startedAt=0,elapsedTimer:ReturnType<typeof setInterval>|undefined,unsubscribeProgress:(()=>void)|undefined;
function stopElapsed(){if(elapsedTimer!==undefined){clearInterval(elapsedTimer);elapsedTimer=undefined;}}
onMounted(()=>{unsubscribeProgress=window.fpcad.onSurfaceProgress(value=>{const active=activeCut.value;if(unwrapping.value&&active&&value.projectId===active.projectId&&value.revision===active.revision&&store.data.project?.id===active.projectId&&store.data.project.revision===active.revision)progress.value=value;});});
onBeforeUnmount(()=>{disposed=true;unsubscribeProgress?.();stopElapsed();activeCut.value=undefined;unwrapping.value=false;});
const unwrapOptions=ref<UnwrapOptions>({method:'arap',partitionStrategy:'design',automaticCuts:true,colorBoundaryCuts:true,normalAngleDeg:60,maxFacesPerPatch:400,iterations:30,optimizeCuts:true,searchPasses:3,maxPieces:500});
const historyPanel=useTemplateRef<HTMLElement>('historyPanel'),history=useDraftHistory(()=>unwrapOptions.value,value=>{unwrapOptions.value=value;},()=>!!historyPanel.value?.getClientRects().length,()=>store.busy);
function colorMode(enabled:boolean){history.begin();unwrapOptions.value.colorBoundaryCuts=enabled;if(!advanced.value)unwrapOptions.value.partitionStrategy='design';history.end();}
function partitionMode(angle:number){history.begin();unwrapOptions.value.normalAngleDeg=angle;if(angle===120||angle===60)unwrapOptions.value.maxFacesPerPatch=angle===120?2000:400;history.end();}
async function unwrap(){if(disposed||props.cutDraftActive||store.busy||!surface.value||!allowanceValid.value||!await applyAllowance()||disposed)return;const p=store.data.project;if(!p||store.busy)return;unwrapping.value=true;activeCut.value={projectId:p.id,revision:p.revision};progress.value=undefined;elapsedSeconds.value=0;startedAt=Date.now();stopElapsed();elapsedTimer=setInterval(()=>{elapsedSeconds.value=Math.max(0,Math.floor((Date.now()-startedAt)/1000));},1000);try{const computed=await store.run(()=>window.fpcad.unwrapSurface(p.id,p.revision,JSON.parse(JSON.stringify({...unwrapOptions.value,partitionStrategy:advanced.value?(unwrapOptions.value.partitionStrategy??'design'):'design'}))),{label:zh.value?'正在计算裁线与展开版型':localize('Computing cut lines and patterns'),cancel:()=>window.fpcad.cancelSurface(p.id,p.revision)});if(computed&&!disposed){allowanceRecomputeRequired.value=false;emit('previewReady');}ack.value=false;}finally{stopElapsed();activeCut.value=undefined;unwrapping.value=false;}}
async function accept(){const p=store.data.project;if(!disposed&&p&&!props.cutDraftActive&&allowanceValid.value&&!allowanceChanged.value&&!allowanceRecomputeRequired.value&&await store.run(()=>window.fpcad.acceptSurface(p.id,p.revision,ack.value))&&!disposed)emit('accepted',store.data.project?.pieces.at(-1)?.id??'');}

</script>

<style scoped>.unwrap-tool-section{padding:15px;border-top:1px solid var(--border)}.unwrap-controls{display:grid;gap:10px}.cut-allowance{display:grid;grid-template-columns:1fr auto;gap:6px;align-items:center;padding:10px;border:1px solid var(--border);border-radius:6px}.cut-allowance label,.cut-allowance small{grid-column:1/-1}.cut-allowance input{width:100%}.run-report{margin-top:15px}.run-report strong{display:block}.run-report button{width:100%;margin-top:10px}.tool-note{font-size:11px;line-height:1.7}small{display:block}label{display:block}.compute-cut-action{display:grid;gap:3px}.pending-cut-draft{font-size:10px;color:var(--warning);line-height:1.5;max-width:190px}.compute-cut-preview{display:flex;align-items:center;justify-content:center;gap:7px;width:100%;padding:9px 11px;background:var(--primary);border-color:var(--primary);color:var(--studio-white);font-size:11px;font-weight:600}.compute-cut-preview:hover{background:var(--primary-hover);border-color:var(--primary-hover)}.compute-cut-preview>.tool-icon{width:17px;height:17px}.compute-cut-preview.in-workspace-toolbar{width:auto;min-height:34px;padding:7px 11px;white-space:nowrap}.candidate-cut-review{display:flex;align-items:flex-start;gap:9px;border:1px solid var(--studio-teal);border-radius:6px;padding:11px;background:var(--accent-soft);margin-bottom:12px;color:var(--studio-teal)}.candidate-cut-review>.tool-icon{width:18px;height:18px;margin-top:1px}.candidate-cut-review strong{font-size:11px}.candidate-cut-review p{font-size:10px;line-height:1.7;margin:4px 0 0;color:var(--text-muted)}.run-report{font-size:11px;line-height:1.7}.run-report>strong{font-size:11px}.run-report>button{background:var(--primary);border-color:var(--primary);color:var(--studio-white);font-size:11px}.run-report>button:hover{background:var(--primary-hover)}.unwrap-controls>label{font-size:11px}.unwrap-controls>small{font-size:10px;line-height:1.7;color:var(--text-muted)}.cut-allowance{background:var(--panel-soft)}.cut-allowance small{font-size:10px;line-height:1.7;color:var(--text-muted)}.surface-progress{padding:9px 10px;border-radius:5px;background:var(--accent-soft);font-size:10px;color:var(--studio-teal)}@media(max-width:1100px){.compute-cut-preview.in-workspace-toolbar{font-size:10px;padding:6px 9px;min-height:32px}}.cut-task-spinner{width:17px;height:17px;border:2px solid color-mix(in srgb,var(--studio-white) 40%,transparent);border-top-color:var(--studio-white);border-radius:50%;animation:cut-task-spin .8s linear infinite}.surface-progress{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:5px 8px;max-width:350px}.surface-progress>div{grid-column:1/-1;line-height:1.6}.surface-progress strong{display:inline}.surface-progress progress{width:100%;height:5px;accent-color:var(--studio-teal)}.surface-progress button{grid-column:2;padding:3px 7px;font-size:10px}.compute-cut-action:has(.surface-progress){min-width:230px}.compute-cut-preview:disabled:has(.cut-task-spinner){opacity:1;cursor:progress}@keyframes cut-task-spin{to{transform:rotate(360deg)}}@media(prefers-reduced-motion:reduce){.cut-task-spinner{animation:none}}</style>
